LEGACY_COLLECTION = "Movies"


def slideshow_to_collection(apps, schema_editor):
    """Move the old slideshow flags into a "Movies" collection and show it on the TV."""
    del schema_editor
    Movie = apps.get_model("posters", "Movie")
    Collection = apps.get_model("posters", "Collection")
    CollectionItem = apps.get_model("posters", "CollectionItem")
    ApplicationSettings = apps.get_model("posters", "ApplicationSettings")
    selected = list(Movie.objects.filter(include_in_rotation=True).values_list("pk", flat=True))
    if not selected:
        return
    collection = Collection.objects.create(name=LEGACY_COLLECTION)
    CollectionItem.objects.bulk_create(
        CollectionItem(collection=collection, movie_id=movie_id) for movie_id in selected
    )
    settings, _ = ApplicationSettings.objects.get_or_create(pk=1)
    settings.active_collection = collection
    settings.save(update_fields=["active_collection"])


def collection_to_slideshow(apps, schema_editor):
    del schema_editor
    Movie = apps.get_model("posters", "Movie")
    ApplicationSettings = apps.get_model("posters", "ApplicationSettings")
    settings = ApplicationSettings.objects.filter(pk=1).first()
    active = settings.active_collection_id if settings else None
    Movie.objects.update(include_in_rotation=False)
    if active:
        Movie.objects.filter(collection_entries__collection_id=active).update(
            include_in_rotation=True
        )


